class VuMeter : public Component, public Timer
{
public:
    VuMeter()
    {
        startTimerHz(30);  // 30 FPS refresh
        level.store(0.0f);
    }

    ~VuMeter() override
    {
        stopTimer();
    }

    void paint(Graphics& g) override
    {
        auto bounds = getLocalBounds().toFloat();

        // Background
        g.setColour(Colours::black);
        g.fillRoundedRectangle(bounds, 4.0f);

        // Calculate meter level
        auto currentLevel = level.load();
        auto meterHeight = bounds.getHeight() * currentLevel;

        // Draw meter fill
        auto meterBounds = bounds.withY(bounds.getHeight() - meterHeight)
                                  .withHeight(meterHeight);

        // Gradient from green to red
        auto gradient = ColourGradient(Colours::green,
                                        bounds.getBottomLeft(),
                                        Colours::red,
                                        bounds.getTopLeft(),
                                        false);
        g.setGradientFill(gradient);
        g.fillRoundedRectangle(meterBounds, 4.0f);

        // Peak marker
        if (peak > 0.0f)
        {
            auto peakY = bounds.getY() + bounds.getHeight() * (1.0f - peak);
            g.setColour(Colours::white);
            g.drawHorizontalLine((int)peakY, bounds.getX(), bounds.getRight());
        }
    }

    void timerCallback() override
    {
        // Smooth decay
        auto current = level.load();
        auto decayed = current * 0.95f;  // Decay factor
        level.store(decayed);
        repaint();
    }

    void setLevel(float newLevel)
    {
        level.store(newLevel);
        if (newLevel > peak)
            peak = newLevel;
    }

private:
    std::atomic<float> level;
    float peak = 0.0f;
};

class StereoMeter : public Component, public Timer
{
public:
    StereoMeter()
    {
        startTimerHz(60);
    }

    void paint(Graphics& g) override
    {
        auto bounds = getLocalBounds().toFloat();
        auto meterWidth = bounds.getWidth() / 2.0f - 2.0f;

        // Left channel
        drawMeter(g, bounds.withWidth(meterWidth), leftLevel);

        // Right channel
        drawMeter(g, bounds.withX(bounds.getX() + meterWidth + 4.0f)
                       .withWidth(meterWidth), rightLevel);
    }

private:
    void drawMeter(Graphics& g, Rectangle<float> bounds, float level)
    {
        // Background
        g.setColour(Colours::darkgrey);
        g.fillRoundedRectangle(bounds, 2.0f);

        // Level bars
        auto numBars = 20;
        auto barHeight = bounds.getHeight() / numBars;

        for (int i = 0; i < numBars; ++i)
        {
            auto barY = bounds.getY() + i * barHeight;
            auto threshold = 1.0f - (float)i / numBars;

            if (level >= threshold)
            {
                // Color based on level
                if (i < 3)  // Top 3 bars (high level)
                    g.setColour(Colours::red);
                else if (i < 6)  // Warning zone
                    g.setColour(Colours::yellow);
                else
                    g.setColour(Colours::green);

                g.fillRoundedRectangle(bounds.withY(barY).withHeight(barHeight - 1.0f), 1.0f);
            }
        }
    }

    std::atomic<float> leftLevel{0.0f};
    std::atomic<float> rightLevel{0.0f};
};

class PeakMeter : public Component, public Timer
{
public:
    PeakMeter()
    {
        startTimerHz(30);
    }

    void pushSample(float sample)
    {
        auto absSample = std::abs(sample);
        if (absSample > currentPeak.load())
        {
            currentPeak.store(absSample);
            peakHoldTime = 0;
        }
    }

    void timerCallback() override
    {
        // Peak hold decay
        peakHoldTime++;
        if (peakHoldTime > holdDuration)
        {
            auto current = currentPeak.load();
            currentPeak.store(current * decayFactor);
        }
        repaint();
    }

    void paint(Graphics& g) override
    {
        auto bounds = getLocalBounds().toFloat();
        auto peak = currentPeak.load();

        // Convert to dB
        auto dB = Decibels::gainToDecibels(peak);
        auto dBRange = 60.0f;  // -60 to 0 dB range
        auto normalized = jlimit(0.0f, 1.0f, (dB + dBRange) / dBRange);

        // Draw meter
        g.setColour(Colours::darkgrey);
        g.fillRoundedRectangle(bounds, 3.0f);

        auto meterBounds = bounds.withWidth(bounds.getWidth() * normalized);

        // Color based on dB level
        Colour meterColour;
        if (dB > -6.0f)
            meterColour = Colours::red;
        else if (dB > -18.0f)
            meterColour = Colours::yellow;
        else
            meterColour = Colours::green;

        g.setColour(meterColour);
        g.fillRoundedRectangle(meterBounds, 3.0f);
    }

private:
    std::atomic<float> currentPeak{0.0f};
    int peakHoldTime = 0;
    int holdDuration = 30;  // Frames to hold
    float decayFactor = 0.98f;
};

class MeterProcessor
{
public:
    void process(AudioBuffer<float>& buffer)
    {
        auto numChannels = buffer.getNumChannels();
        auto numSamples = buffer.getNumSamples();

        for (int channel = 0; channel < numChannels; ++channel)
        {
            auto* channelData = buffer.getReadPointer(channel);

            // Calculate RMS
            float sumSquared = 0.0f;
            for (int i = 0; i < numSamples; ++i)
            {
                sumSquared += channelData[i] * channelData[i];
            }
            auto rms = std::sqrt(sumSquared / numSamples);

            // Calculate Peak
            auto peak = 0.0f;
            for (int i = 0; i < numSamples; ++i)
            {
                peak = std::max(peak, std::abs(channelData[i]));
            }

            // Store levels (atomic for thread safety)
            if (channel == 0)
                leftLevel.store(rms);
            else if (channel == 1)
                rightLevel.store(rms);
        }
    }

    float getLeftLevel() const { return leftLevel.load(); }
    float getRightLevel() const { return rightLevel.load(); }

private:
    std::atomic<float> leftLevel{0.0f};
    std::atomic<float> rightLevel{0.0f};
};

// Avoid unnecessary repaints
void setLevel(float newLevel)
{
    if (std::abs(newLevel - currentLevel) > 0.01f)
    {
        currentLevel = newLevel;
        repaint();
    }
}

